export const envelope = [26, 34, 26];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;

  // ---------------------------------------------------------
  // THEME ROLES & PALETTE RESOLUTION
  // ---------------------------------------------------------
  const stonePri = api.theme.stone?.primary ?? "minecraft:stone_bricks";
  const stoneAcc = api.theme.stone?.accent ?? "minecraft:cracked_stone_bricks";
  const stoneStairs = api.theme.stone?.stairs ?? "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab ?? "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall ?? "minecraft:stone_brick_wall";

  const groundPlinth = api.theme.ground?.plinth ?? "minecraft:andesite";
  const groundPavement = api.theme.ground?.pavement ?? "minecraft:cobblestone";

  const woodPlanks = api.theme.wood?.planks ?? "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log ?? "minecraft:spruce_log";
  const woodFence = api.theme.wood?.fence ?? "minecraft:spruce_fence";
  const woodDoor = api.theme.wood?.door ?? "minecraft:spruce_door";

  const roofSolid = api.theme.roof?.solid ?? "minecraft:dark_oak_planks";
  const roofStairs = api.theme.roof?.stairs ?? "minecraft:dark_oak_stairs";
  const roofSlab = api.theme.roof?.slab ?? "minecraft:dark_oak_slab";

  const ironBars = "minecraft:iron_bars";
  const bannerRed = "minecraft:red_wool";
  const bannerGold = "minecraft:yellow_wool";
  const lantern = "minecraft:lantern[hanging=false]";

  // ---------------------------------------------------------
  // HELPER FUNCTIONS
  // ---------------------------------------------------------
  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  function randomStone() {
    const r = api.random();
    if (r < 0.18) return stoneAcc;
    if (r < 0.26) return groundPlinth;
    return stonePri;
  }

  function fill(x1, y1, z1, x2, y2, z2, blockOrFn) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          const b = typeof blockOrFn === "function" ? blockOrFn(x, y, z) : blockOrFn;
          set(x, y, z, b);
        }
      }
    }
  }

  function stair(facing, half = "bottom", shape = "straight", mat = stoneStairs) {
    const base = mat.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function slab(type = "bottom", mat = stoneSlab) {
    const base = mat.split("[")[0];
    return `${base}[type=${type}]`;
  }

  // ---------------------------------------------------------
  // 1. FOOTPRINT & TERRAIN CONFORMITY (RULE 5 & 6)
  // ---------------------------------------------------------
  function isFootprint(x, z) {
    // Corner towers (NW, NE, SW, SE)
    if (x >= 1 && x <= 8 && z >= 1 && z <= 8) return true;
    if (x >= 17 && x <= 24 && z >= 1 && z <= 8) return true;
    if (x >= 1 && x <= 8 && z >= 17 && z <= 24) return true;
    if (x >= 17 && x <= 24 && z >= 17 && z <= 24) return true;
    // Central keep core body & bays
    if (x >= 3 && x <= 22 && z >= 3 && z <= 22) return true;
    // North grand staircase
    if (x >= 10 && x <= 15 && z >= 0 && z <= 3) return true;
    return false;
  }

  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      if (isFootprint(x, z)) {
        const gh = api.heightAt(x, z);
        const bottomY = Math.min(0, gh);
        // Step foundation skirts down to local terrain
        for (let y = bottomY; y <= 0; y++) {
          set(x, y, z, y === 0 ? groundPlinth : groundPavement);
        }
        if (gh > 0) {
          for (let y = 0; y <= gh; y++) {
            set(x, y, z, groundPlinth);
          }
        }
      }
    }
  }

  // ---------------------------------------------------------
  // 2. BATTERED BASE / TALUS (y = 0 to 4)
  // ---------------------------------------------------------
  // Solid foundation platform at y=0
  fill(3, 0, 3, 22, 0, 22, groundPlinth);

  // Sloped battered skirts along wall bays at y=1..3
  // North talus (facing south)
  for (let x = 8; x <= 17; x++) {
    set(x, 1, 3, stair("south", "bottom"));
    set(x, 2, 4, stair("south", "bottom"));
  }
  // South talus (facing north)
  for (let x = 8; x <= 17; x++) {
    set(x, 1, 22, stair("north", "bottom"));
    set(x, 2, 21, stair("north", "bottom"));
  }
  // West talus (facing east)
  for (let z = 8; z <= 17; z++) {
    set(3, 1, z, stair("east", "bottom"));
    set(4, 2, z, stair("east", "bottom"));
  }
  // East talus (facing west)
  for (let z = 8; z <= 17; z++) {
    set(22, 1, z, stair("west", "bottom"));
    set(21, 2, z, stair("west", "bottom"));
  }

  // Battered corners at 4 towers (y=1)
  const towerCorners = [
    [1, 1, 8, 8],     // NW
    [17, 1, 24, 8],   // NE
    [1, 17, 8, 24],   // SW
    [17, 17, 24, 24], // SE
  ];

  for (const [x1, z1, x2, z2] of towerCorners) {
    for (let x = x1; x <= x2; x++) {
      set(x, 1, z1, stair("south", "bottom"));
      set(x, 1, z2, stair("north", "bottom"));
    }
    for (let z = z1; z <= z2; z++) {
      set(x1, 1, z, stair("east", "bottom"));
      set(x2, 1, z, stair("west", "bottom"));
    }
  }

  // ---------------------------------------------------------
  // 3. MAIN KEEP SHELL & TOWERS (y = 1 to 25)
  // ---------------------------------------------------------
  // Corner Clasping Towers (NW, NE, SW, SE)
  const towers = [
    [2, 2, 7, 7],     // NW Tower
    [18, 2, 23, 7],   // NE Tower
    [2, 18, 7, 23],   // SW Tower
    [18, 18, 23, 23], // SE Tower
  ];

  for (const [tx1, tz1, tx2, tz2] of towers) {
    fill(tx1, 1, tz1, tx2, 25, tz2, randomStone);
  }

  // Main Keep Curtain Walls
  // North & South walls
  fill(5, 1, 5, 20, 25, 6, randomStone);
  fill(5, 1, 19, 20, 25, 20, randomStone);
  // West & East walls
  fill(5, 1, 5, 6, 25, 20, randomStone);
  fill(19, 1, 5, 20, 25, 20, randomStone);

  // Pilaster Buttresses along wall centers (y=4..24)
  fill(12, 4, 4, 13, 24, 4, randomStone);   // North pilaster
  fill(12, 4, 21, 13, 24, 21, randomStone); // South pilaster
  fill(4, 4, 12, 4, 24, 13, randomStone);   // West pilaster
  fill(21, 4, 12, 21, 24, 13, randomStone); // East pilaster

  // String course bands (architectural tiers)
  for (let yBand of [7, 16]) {
    for (let x = 7; x <= 18; x++) {
      set(x, yBand, 4, stair("south", "top"));
      set(x, yBand, 21, stair("north", "top"));
    }
    for (let z = 7; z <= 18; z++) {
      set(4, yBand, z, stair("east", "top"));
      set(21, yBand, z, stair("west", "top"));
    }
  }

  // ---------------------------------------------------------
  // 4. NORTH FOREBUILDING & FORTIFIED PORTAL
  // ---------------------------------------------------------
  // Grand Entry Stairway (ascending to portal at y=4)
  for (let x = 11; x <= 14; x++) {
    set(x, 1, 0, stair("north", "bottom"));
    set(x, 1, 1, groundPlinth);
    set(x, 2, 1, stair("north", "bottom"));
    set(x, 1, 2, groundPlinth);
    set(x, 2, 2, groundPlinth);
    set(x, 3, 2, stair("north", "bottom"));
    set(x, 1, 3, groundPlinth);
    set(x, 2, 3, groundPlinth);
    set(x, 3, 3, groundPlinth);
    set(x, 4, 3, groundPlinth);
  }

  // Stairway stone parapets
  for (let z = 0; z <= 3; z++) {
    set(10, z + 1, z, stoneWall);
    set(15, z + 1, z, stoneWall);
  }

  // Fortified Gateway Piers (X=11 & 14, y=4..7)
  fill(11, 4, 4, 11, 7, 5, randomStone);
  fill(14, 4, 4, 14, 7, 5, randomStone);
  // Arched Portal Opening
  set(12, 4, 4, "minecraft:air");
  set(13, 4, 4, "minecraft:air");
  set(12, 5, 4, "minecraft:air");
  set(13, 5, 4, "minecraft:air");
  set(12, 6, 4, stair("west", "top"));
  set(13, 6, 4, stair("east", "top"));
  fill(11, 7, 4, 14, 7, 4, randomStone);

  // Portcullis & Doorway inside
  set(12, 4, 5, ironBars);
  set(13, 4, 5, ironBars);
  set(12, 5, 5, ironBars);
  set(13, 5, 5, ironBars);
  set(12, 4, 6, "minecraft:air");
  set(13, 4, 6, "minecraft:air");
  set(12, 5, 6, "minecraft:air");
  set(13, 5, 6, "minecraft:air");

  // ---------------------------------------------------------
  // 5. INTERIOR TIERS & FLOORS
  // ---------------------------------------------------------
  // Tier 1: Undercroft / Vault (y=1..6)
  fill(7, 0, 7, 18, 0, 18, groundPlinth);
  // Central vaulted stone pillars
  fill(10, 1, 10, 10, 6, 10, randomStone);
  fill(15, 1, 10, 15, 6, 10, randomStone);
  fill(10, 1, 15, 10, 6, 15, randomStone);
  fill(15, 1, 15, 15, 6, 15, randomStone);

  // Tier 2: Great Hall Floor (y=7)
  fill(7, 7, 7, 18, 7, 18, woodPlanks);
  // Hall timber ceiling beams (y=15)
  for (let z = 8; z <= 17; z += 3) {
    fill(7, 15, z, 18, 15, z, woodLog);
  }

  // Tier 3: Lord's Solar / Quarters Floor (y=16)
  fill(7, 16, 7, 18, 16, 18, woodPlanks);

  // Great Hall Fireplace & Chimney (West wall, X: 5..6, Z: 11..14)
  fill(5, 8, 11, 6, 26, 14, randomStone);
  // Hearth niche
  fill(6, 8, 12, 6, 10, 13, "minecraft:air");
  set(6, 11, 12, stair("south", "top"));
  set(6, 11, 13, stair("north", "top"));

  // Hollow out the interior chambers for compiler furnishing
  fill(7, 1, 7, 18, 6, 18, (x, y, z) => {
    // Keep pillars solid
    if ((x === 10 || x === 15) && (z === 10 || z === 15)) return randomStone();
    return "minecraft:air";
  });
  fill(7, 8, 7, 18, 14, 18, (x, y, z) => {
    if (x <= 6 && z >= 11 && z <= 14) return randomStone(); // Chimney breast
    return "minecraft:air";
  });
  fill(7, 17, 7, 18, 24, 18, (x, y, z) => {
    if (x <= 6 && z >= 11 && z <= 14) return randomStone(); // Chimney
    return "minecraft:air";
  });

  // ---------------------------------------------------------
  // 6. EMBRASURES, ARROW SLITS & GOTHIC WINDOWS
  // ---------------------------------------------------------
  // Arrow slits in Undercroft (y=3)
  const arrowSlits = [
    [9, 3, 4, "south"], [16, 3, 4, "south"],   // North
    [9, 3, 21, "north"], [16, 3, 21, "north"], // South
    [4, 3, 9, "east"], [4, 3, 16, "east"],     // West
    [21, 3, 9, "west"], [21, 3, 16, "west"],   // East
  ];
  for (const [x, y, z, facing] of arrowSlits) {
    set(x, y, z, ironBars);
  }

  // Great Hall Gothic Arched Windows (y=10..13)
  // South windows
  for (const wx of [9, 10, 15, 16]) {
    fill(wx, 10, 20, wx, 12, 20, ironBars);
    set(wx, 13, 20, stair("north", "top"));
  }
  // East windows
  for (const wz of [9, 10, 15, 16]) {
    fill(20, 10, wz, 20, 12, wz, ironBars);
    set(20, 13, wz, stair("west", "top"));
  }
  // North windows
  for (const wx of [9, 16]) {
    fill(wx, 10, 5, wx, 12, 5, ironBars);
    set(wx, 13, 5, stair("south", "top"));
  }

  // Lord's Solar High Windows (y=19..21)
  for (const wx of [10, 15]) {
    set(wx, 19, 5, ironBars);
    set(wx, 20, 5, stair("south", "top"));
    set(wx, 19, 20, ironBars);
    set(wx, 20, 20, stair("north", "top"));
  }
  for (const wz of [10, 15]) {
    set(20, 19, wz, ironBars);
    set(20, 20, wz, stair("west", "top"));
    set(5, 19, wz, ironBars);
    set(5, 20, wz, stair("east", "top"));
  }

  // ---------------------------------------------------------
  // 7. ROOF DECK, MACHICOLATIONS & BATTLEMENTS (y = 25 to 29)
  // ---------------------------------------------------------
  // Roof Fighting Platform Floor (y=25)
  fill(5, 25, 5, 20, 25, 20, randomStone);

  // Cantilevered Corbel Table (Machicolations) at y=25
  // North & South corbels
  for (let x = 4; x <= 21; x++) {
    set(x, 25, 4, stair("south", "top"));
    set(x, 25, 21, stair("north", "top"));
  }
  // West & East corbels
  for (let z = 4; z <= 21; z++) {
    set(4, 25, z, stair("east", "top"));
    set(21, 25, z, stair("west", "top"));
  }

  // Parapet Base (y=26..27)
  // North parapet
  fill(4, 26, 4, 21, 27, 4, randomStone);
  // South parapet
  fill(4, 26, 21, 21, 27, 21, randomStone);
  // West parapet
  fill(4, 26, 4, 4, 27, 21, randomStone);
  // East parapet
  fill(21, 26, 4, 21, 27, 21, randomStone);

  // Crenellations & Merlons (y=28..29)
  // North & South battlements
  for (let x = 4; x <= 21; x++) {
    if (x % 2 === 0) {
      set(x, 28, 4, randomStone());
      set(x, 29, 4, stoneWall);
      set(x, 28, 21, randomStone());
      set(x, 29, 21, stoneWall);
    } else {
      set(x, 28, 4, slab("bottom"));
      set(x, 28, 21, slab("bottom"));
    }
  }
  // West & East battlements
  for (let z = 4; z <= 21; z++) {
    if (z % 2 === 0) {
      set(4, 28, z, randomStone());
      set(4, 29, z, stoneWall);
      set(21, 28, z, randomStone());
      set(21, 29, z, stoneWall);
    } else {
      set(4, 28, z, slab("bottom"));
      set(21, 28, z, slab("bottom"));
    }
  }

  // ---------------------------------------------------------
  // 8. CORNER BARTIZANS & TOWER SUMMITS (y = 25 to 33)
  // ---------------------------------------------------------
  for (const [tx1, tz1, tx2, tz2] of towers) {
    // Solid tower walls rising above main roof deck (y=26..29)
    fill(tx1, 26, tz1, tx2, 29, tz2, (x, y, z) => {
      if (x === tx1 || x === tx2 || z === tz1 || z === tz2) return randomStone();
      return "minecraft:air"; // Bartizan interior
    });

    // Floor of bartizan fighting top (y=29)
    fill(tx1, 29, tz1, tx2, 29, tz2, randomStone);

    // Corbeling out around bartizans (y=29)
    for (let x = tx1; x <= tx2; x++) {
      set(x, 29, tz1 - 1, stair("south", "top"));
      set(x, 29, tz2 + 1, stair("north", "top"));
    }
    for (let z = tz1; z <= tz2; z++) {
      set(tx1 - 1, 29, z, stair("east", "top"));
      set(tx2 + 1, 29, z, stair("west", "top"));
    }

    // Parapet & Merlons on Turrets (y=30..31)
    for (let x = tx1 - 1; x <= tx2 + 1; x++) {
      for (let z = tz1 - 1; z <= tz2 + 1; z++) {
        const isBorder = (x === tx1 - 1 || x === tx2 + 1 || z === tz1 - 1 || z === tz2 + 1);
        if (isBorder) {
          set(x, 30, z, randomStone());
          if ((x + z) % 2 === 0) {
            set(x, 31, z, stoneWall);
          } else {
            set(x, 31, z, slab("bottom"));
          }
        }
      }
    }
  }

  // Conical / Hipped Timber Roof Caps on NW & SE Turrets (y=31..33)
  // NW Turret Roof Cap
  fill(3, 31, 3, 6, 31, 6, roofSolid);
  for (let x = 2; x <= 7; x++) {
    set(x, 31, 2, stair("south", "bottom", "straight", roofStairs));
    set(x, 31, 7, stair("north", "bottom", "straight", roofStairs));
  }
  for (let z = 2; z <= 7; z++) {
    set(2, 31, z, stair("east", "bottom", "straight", roofStairs));
    set(7, 31, z, stair("west", "bottom", "straight", roofStairs));
  }
  fill(4, 32, 4, 5, 32, 5, roofSolid);
  set(4, 33, 4, woodFence);
  set(4, 33, 5, ironBars);

  // SE Turret Roof Cap
  fill(19, 31, 19, 22, 31, 22, roofSolid);
  for (let x = 18; x <= 23; x++) {
    set(x, 31, 18, stair("south", "bottom", "straight", roofStairs));
    set(x, 31, 23, stair("north", "bottom", "straight", roofStairs));
  }
  for (let z = 18; z <= 23; z++) {
    set(18, 31, z, stair("east", "bottom", "straight", roofStairs));
    set(23, 31, z, stair("west", "bottom", "straight", roofStairs));
  }
  fill(20, 32, 20, 21, 32, 21, roofSolid);
  set(21, 33, 21, woodFence);
  set(21, 33, 20, ironBars);

  // NE & SW Turrets: Tall Heraldic Standards / Banners (y=30..33)
  // NE Flagstaff & Royal Banner
  for (let y = 30; y <= 33; y++) {
    set(20, y, 4, woodFence);
  }
  set(19, 33, 4, bannerGold);
  set(19, 32, 4, bannerRed);
  set(19, 31, 4, bannerGold);
  set(18, 33, 4, bannerRed);
  set(18, 32, 4, bannerGold);

  // SW Flagstaff & Banner
  for (let y = 30; y <= 33; y++) {
    set(4, y, 20, woodFence);
  }
  set(5, 33, 20, bannerRed);
  set(5, 32, 20, bannerGold);
  set(5, 31, 20, bannerRed);
  set(6, 33, 20, bannerGold);
  set(6, 32, 20, bannerRed);

  // ---------------------------------------------------------
  // 9. CENTRAL WATCHTOWER & ROOF ACCESS (y = 25 to 33)
  // ---------------------------------------------------------
  // Central Watchtower (X: 11..14, Z: 11..14)
  fill(11, 25, 11, 14, 30, 14, (x, y, z) => {
    if (x === 11 || x === 14 || z === 11 || z === 14) return randomStone();
    return "minecraft:air";
  });

  // Watchtower Doorway (facing North onto roof deck)
  set(12, 26, 11, "minecraft:air");
  set(13, 26, 11, "minecraft:air");
  set(12, 27, 11, stair("west", "top"));
  set(13, 27, 11, stair("east", "top"));

  // Watchtower roof floor & battlements (y=30..31)
  fill(11, 30, 11, 14, 30, 14, randomStone);
  for (let x = 11; x <= 14; x++) {
    set(x, 31, 11, stoneWall);
    set(x, 31, 14, stoneWall);
  }
  for (let z = 11; z <= 14; z++) {
    set(11, 31, z, stoneWall);
    set(14, 31, z, stoneWall);
  }

  // Central Great Mast / Keep Spire (y=31..33)
  fill(12, 31, 12, 13, 31, 13, randomStone);
  set(12, 32, 12, woodFence);
  set(12, 33, 12, woodFence);
  set(13, 33, 12, bannerGold);
  set(13, 32, 12, bannerRed);

  // Chimney pot on roof deck (West side)
  fill(5, 26, 12, 6, 28, 13, randomStone);
  set(5, 29, 12, stoneWall);
  set(6, 29, 13, stoneWall);

  // ---------------------------------------------------------
  // 10. RETURN RESULTS WITH HONEST SEAT, ANCHORS & INTERIORS
  // ---------------------------------------------------------
  return {
    name: "castle_keep",
    seatY: 0,
    anchors: {
      front: [13, 0, 0],
      door: [13, 4, 4],
      summit: [12, 33, 12],
    },
    interiors: [
      {
        min: [7, 1, 7],
        max: [18, 6, 18],
        kind: "vault",
      },
      {
        min: [7, 8, 7],
        max: [18, 14, 18],
        kind: "hall",
      },
      {
        min: [7, 17, 7],
        max: [18, 24, 18],
        kind: "quarters",
      },
    ],
  };
}
